begin;
do $continue$ declare e record;nv bigint;before_count bigint;after_count bigint;after_id bigint; begin select * into e from public._m029_recovery_expected;perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',e.owner_user_id::text,true);select count(*) into before_count from public.operational_activity_events where owner_user_id=e.owner_user_id;select object_version into nv from public.save_personal_operational_record_v2(e.content_id,'CONTENT','Recovery content continued',jsonb_build_object('status','ACTIVE','body','safe continued'),'ACTIVE',e.content_version,'m029:recovery:continue');select count(*),max(id) into after_count,after_id from public.operational_activity_events where owner_user_id=e.owner_user_id;if nv<>e.content_version+1 or after_count<>before_count+1 or after_id<=e.timeline_max_id then raise exception 'm029_recovery_continuation_failed';end if;end $continue$;
select jsonb_build_object('result','M029_RECOVERY_CONTINUATION_PASS','identity_preserved',true,'version_continued',true,'timeline_continued',true,'silent_overwrite',false) verification;
rollback;
